package com.novacommerce.inventory.integration;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.novacommerce.inventory.domain.inventory.InventoryItem; import com.novacommerce.inventory.infrastructure.persistence.InventoryItemRepository; import java.time.Instant; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class InventoryFastIntegrationTests {@Autowired MockMvc mvc;@Autowired InventoryItemRepository items;UUID id;
 @BeforeEach void setup(){items.deleteAll();id=UUID.randomUUID();items.save(new InventoryItem(id,10,Instant.now()));}
 @Test void publicAvailabilityAndSecurityRules()throws Exception{mvc.perform(get("/api/v1/inventory/variants/{id}",id)).andExpect(status().isOk()).andExpect(jsonPath("$.availableQuantity").value(10));String body="{\"quantityDelta\":5,\"reason\":\"restock\"}";mvc.perform(post("/api/v1/admin/inventory/{id}/adjustments",id).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isForbidden());mvc.perform(post("/api/v1/admin/inventory/{id}/adjustments",id).with(jwt().authorities(()->"ROLE_CUSTOMER")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isForbidden());mvc.perform(post("/api/v1/admin/inventory/{id}/adjustments",id).with(jwt().jwt(j->j.subject(UUID.randomUUID().toString())).authorities(()->"ROLE_ADMIN")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.onHand").value(15));}
 @Test void reservationValidationAndAuthentication()throws Exception{String request="{\"items\":[{\"variantId\":\""+id+"\",\"quantity\":1}]}";mvc.perform(post("/api/v1/inventory/reservations").with(csrf()).header("Idempotency-Key","a").contentType(MediaType.APPLICATION_JSON).content(request)).andExpect(status().isUnauthorized());mvc.perform(post("/api/v1/inventory/reservations").with(jwt().jwt(j->j.subject(UUID.randomUUID().toString())).authorities(()->"ROLE_CUSTOMER")).with(csrf()).header("Idempotency-Key","a").contentType(MediaType.APPLICATION_JSON).content(request)).andExpect(status().isCreated());}
}
